contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // amount: how much to deposit into c before attempting withdrawAll
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0, "amount must be positive");
        // ensure this contract has enough balance to deposit
        require(address(this).balance >= amount, "insufficient test contract balance");

        // record balances before deposit
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        // deposit amount into c (top-level state-changing call)
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // record balances after deposit and before withdraw
        uint afterDepositThis = address(this).balance;
        uint afterDepositC = address(c).balance;

        bool reverted;
        // call withdrawAll (top-level state-changing call must be its own statement)
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterThis = address(this).balance;
        uint afterC = address(c).balance;

        // General rule: after depositing `amount`, withdrawAll either reverts, or
        // it transfers exactly `amount` back to this contract and reduces c's balance by exactly `amount`.
        // Expressed: if not reverted then this contract gained amount and c lost amount.
        assert(reverted || (afterThis == afterDepositThis + amount && afterC == afterDepositC - amount));
    }

    receive() external payable {}
}

